function renderAccountDetail(id){const a=state.accounts.find(x=>x.id===id);if(!a){activeAccountDetailId=null;return;}const accountsView=document.getElementById('accounts-view');let root=document.getElementById('account-detail-view');if(!root){root=document.createElement('div');root.id='account-detail-view';accountsView.append(root);}document.getElementById('accounts-list').hidden=true;accountsView.querySelector('.page-heading').hidden=true;const rows=accountTransactions(id);root.hidden=false;root.innerHTML=`<div class="page-heading account-detail-page-heading"><div><button type="button" class="secondary" id="account-detail-back">← Accounts</button><p class="eyebrow">Account</p><h1>${esc(a.name)}</h1>${a.notes?`<p class="account-detail-note">${esc(a.notes)}</p>`:''}</div><div class="account-detail-actions"><strong>${money(accountBalance(a))}</strong><button type="button" class="secondary" id="account-detail-edit">Edit account</button></div></div><div class="account-transaction-list account-detail-table">${rows.length?`<table><thead><tr><th></th><th>Date</th><th>Payee</th><th>Category</th><th>Amount</th><th>Status</th><th>Delete</th></tr></thead><tbody>${rows.map(t=>{const locked=!!t.reconciled;const amount=accountTransactionAmount(t,id);return `<tr><td><input type="checkbox" data-account-tx="${esc(t.id)}"></td><td>${esc(t.date)}</td><td>${esc(transactionLabel(t))}</td><td>${esc(t.category||({income:'Income',transfer:'Transfer'}[t.type]||'—'))}</td><td class="${amount>=0?'amount-in':'amount-out'}">${amount>=0?'+':'−'}${money(Math.abs(amount))}</td><td><button type="button" class="lock-toggle ${locked?'locked':'unlocked'}" data-toggle-reconciled="${esc(t.id)}" title="${locked?'Reconciled — click to mark not reconciled':'Not reconciled — click to reconcile'}" aria-label="${locked?'Reconciled':'Not reconciled'}">🔒</button></td><td><button type="button" class="delete-transaction" data-delete-account-transaction="${esc(t.id)}" title="Delete transaction" aria-label="Delete transaction">✕</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No transactions for this account.</div>'}</div><div class="modal-actions account-detail-actions-row"><button class="primary" id="reconcile-selected" ${rows.length?'':'disabled'} title="Reconcile selected">🔒 Reconcile selected</button></div>`;root.querySelector('#account-detail-back').onclick=()=>{activeAccountDetailId=null;renderAccounts();};root.querySelector('#account-detail-edit').onclick=()=>openAccountEditor(id);root.querySelectorAll('[data-toggle-reconciled]').forEach(b=>b.onclick=()=>{const t=state.transactions.find(x=>x.id===b.dataset.toggleReconciled);if(t){t.reconciled=!t.reconciled;save();renderAccountDetail(id);}});root.querySelectorAll('[data-delete-account-transaction]').forEach(b=>b.onclick=()=>deleteTransaction(b.dataset.deleteAccountTransaction,()=>renderAccountDetail(id)));root.querySelector('#reconcile-selected').onclick=()=>{root.querySelectorAll('[data-account-tx]:checked').forEach(box=>{const t=state.transactions.find(x=>x.id===box.dataset.accountTx);if(t)t.reconciled=true;});save();renderAccountDetail(id);};}
