function openAccountEditor(id){const a=state.accounts.find(x=>x.id===id);if(!a)return;const m=modal(`Edit ${esc(a.name)}`,`<div class="form-grid"><label class="form-field full">Account name<input id="edit-account-name" value="${esc(a.name)}"></label><label class="form-field full">Notes<input id="edit-account-notes" value="${esc(a.notes||'')}" placeholder="Optional note"></label><label class="form-field">Type<select id="edit-account-type"><option value="checking" ${a.type==='checking'?'selected':''}>Checking</option><option value="savings" ${a.type==='savings'?'selected':''}>Savings</option><option value="credit" ${a.type==='credit'?'selected':''}>Credit card</option></select></label><label class="form-field">Opening balance<input id="edit-account-opening" type="number" step="0.01" value="${Number(a.openingBalance||0)}"></label></div><div class="modal-actions"><button class="secondary" data-close>Cancel</button><button class="primary" id="save-account-edit">Save changes</button></div>`);m.querySelector('[data-close]').onclick=closeModal;m.querySelector('#save-account-edit').onclick=()=>{const name=m.querySelector('#edit-account-name').value.trim();if(!name)return;const type=m.querySelector('#edit-account-type').value;const openingBalance=Number(m.querySelector('#edit-account-opening').value||0);const oldCounted=a.type==='credit'?0:Number(a.openingBalance||0);const newCounted=type==='credit'?0:openingBalance;if(newCounted!==oldCounted){state.openingFunds=Number(state.openingFunds||0)+newCounted-oldCounted;if(!state.openingFundsMonth&&newCounted>0)state.openingFundsMonth=activeMonth;}a.name=name;a.notes=m.querySelector('#edit-account-notes').value.trim();a.type=type;a.openingBalance=openingBalance;save();closeModal();render();};}
